 L.push(pos===0?kp+'x + '+q+' = '+R:kp+'x + '+kq+' = '+R);
 var sub=pos===0?q:kq,r2=R-sub;L.push(kp+'x = '+R+(pos===1?' + ':' − ')+sub);var rr=pos===1?R+sub:R-sub;
