/* ===== personalization: placement check, recency/mode weighted picking, adaptive lesson length, refresher gating, pacing ===== */
(function(){
var M=P.meta,REF=M.refresh||null;
S.ema=S.ema||{};S.ls=S.ls||{};S.rfu=S.rfu||{};S.ld=S.ld||{};
function emaOf(t){return S.ema[t]!==undefined?S.ema[t]:.5}
function ab(t){return Math.round(100/(1+Math.exp(-(S.th[t]||0))))}
/* recency-weighted accuracy */
var _cu=coachUpdate;coachUpdate=function(q,ok,helped){_cu.apply(this,arguments);S.ema[q.t]=Math.round((emaOf(q.t)*.75+(ok&&!helped?1:ok?.6:0)*.25)*1000)/1000;S.ls[q.id]=Date.now()};
function pace(t){var st=S.stat[t]||[0,0],e=emaOf(t),a=ab(t);if(st[1]<2&&S.dgr&&S.dgr[t]===undefined)return 'mid';if(a<38||e<.5)return 'weak';if(a>=72&&e>=.8)return 'strong';return 'mid'}
window.__pace=pace;
function modeW(){var k=Z&&Z.kind;return k==='review'?{due:2,nw:.3,weak:.6}:k==='lesson'?{due:.6,nw:1.2,weak:.8}:(k==='quick'||k==='adaptive')?{due:.9,nw:.5,weak:1.5}:k==='mock'?{due:.3,nw:.6,weak:1}:{due:1,nw:.5,weak:1}}
coachPick=function(o){
 var tg=o.target||TARGET,ex=o.exclude||[],last=o.last||[],best=null,bs=-1e9,d=dayN(),W=modeW(),now=Date.now();
 for(var i=0;i<QS.length;i++){var q=QS[i];
  if(o.topics&&o.topics.indexOf(q.t)<0)continue;if(ex.indexOf(q.id)>-1)continue;if(o.types&&o.types.indexOf(q.type)<0)continue;
  var m=S.mem[q.id],s=0,p=.6*pOK(q.t,q)+.4*Math.min(.98,Math.max(.02,emaOf(q.t)*.6+pOK(q.t,q)*.4));
  if(!m)s+=W.nw;else if(m[1]<=d)s+=W.due*((o.dueLeft===undefined||o.dueLeft>0)?1+Math.min(.5,.05*(d-m[1])):.1);else s-=2.5;
  if(S.ls[q.id]&&now-S.ls[q.id]<20*60000)s-=3;
  s-=6*Math.abs(p-tg);
  if(last[last.length-1]===q.t)s-=.7;else if(last.indexOf(q.t)>-1)s-=.3;
  s+=W.weak*.8*(1-emaOf(q.t));
  s+=Math.random()*.35;if(s>bs){bs=s;best=q}}
 return best&&best.id};
/* adaptive lesson length: weak topics get gentler extra steps, mastered topics get shorter harder lessons */
var _ls=lessonSteps;lessonSteps=function(u,L){var st=_ls(u,L),pc=pace(u.id),used=st.filter(function(x){return x.k==='try'}).map(function(x){return x.it.id}),add=function(n,tg){var o=[];for(var i=0;i<n;i++){var id=coachPick({topics:[u.id],exclude:used.concat(o),target:tg});if(!id)break;o.push(id);st.push({k:'try',it:mkItem(id)})}};
 if(pc==='weak'){st.forEach(function(x){if(x.k==='card')x.slow=1});add(2,.9);add(1,.8)}
 else if(pc==='strong'){st=st.filter(function(x){return x.k!=='try'||x.it.q.l>1||Math.random()<.3});add(2,.6)}
 return st};
/* refresher gating */
function refUnits(){return REF?UN.filter(function(u){return REF[u.id]}):[]}
function refWhy(t){if(!REF||!REF[t])return null;if(S.rfu[t])return 'Unlocked by you';var d=S.dgr&&S.dgr[t];if(d===0)return 'Placement check: needs review';var adj=REF[t],bad=adj.filter(function(a){var st=S.stat[a]||[0,0];return st[1]>=6&&emaOf(a)<.62});if(bad.length)return 'Struggling with '+bad.map(function(a){return TOP[a].name}).join(', ');var st=S.stat[t]||[0,0];if(st[1]>=6&&emaOf(t)<.6)return 'Recent misses';return null}
var FULL=UN;
function withMain(fn){var keep=UN;UN=FULL.filter(function(u){return !REF||!REF[u.id]||refWhy(u.id)});try{return fn()}finally{UN=keep}}
if(REF){var _nl=nextLesson;nextLesson=function(){return withMain(_nl)}}
var _vl=viewLearn;
viewLearn=function(){var h=withMain(_vl);
 if(!S.dg)h=h.replace(/(<div class="cont">|<details class="unit")/,'<div class="card dgc"><div style="flex:1"><b>Placement check</b></div><button class="btn sm" id="dgs">Start</button></div>$1');
 var tgt=M.target;if(tgt){var left=0;FULL.forEach(function(u){if(REF&&REF[u.id]&&!refWhy(u.id))return;var us=S.un[u.id]||{d:{}};u.lessons.forEach(function(L){if(!us.d[L.id])left++})});var wk=Math.max(1,(new Date(tgt+'T12:00:00')-Date.now())/6048e5),need=Math.ceil(left/wk),did=0;for(var i=0;i<7;i++){var dk=new Date();dk.setDate(dk.getDate()-i);var k=dk.getFullYear()+'-'+('0'+(dk.getMonth()+1)).slice(-2)+'-'+('0'+dk.getDate()).slice(-2);did+=S.ld[k]||0}
  h=h.replace(/(<div class="cont">)/,'<div class="pace"><span>'+left+' lessons left · '+need+'/week to finish by spring</span><b class="'+(did>=need?'ok':'')+'">'+did+' this week</b></div>$1')}
 var rf=refUnits().filter(function(u){return !refWhy(u.id)});
 if(rf.length)h+='<details class="unit refr"><summary class="unit-h"><div style="flex:1"><h3>Algebra refreshers</h3><div class="small mute">Only if you need them · '+rf.length+' topics</div></div></summary><div class="lessons rfl">'+rf.map(function(u){return '<button class="btn sec sm" data-rfu="'+u.id+'">'+esc(u.title)+'</button>'}).join('')+'</div></details>';
 refUnits().forEach(function(u){var w=refWhy(u.id);if(w)h=h.replace('<h3>'+esc(u.title)+'</h3>','<h3>'+esc(u.title)+' <span class="tag">Refresher</span></h3><div class="small" style="color:var(--pri-t)">'+esc(w)+'</div>')});
 return h};
document.addEventListener('click',function(e){var r=e.target.closest&&e.target.closest('[data-rfu]');if(r){S.rfu[r.dataset.rfu]=1;save();toast&&toast('Added to your path');route();return}
 if(e.target.id==='dgs')startDiag();});
/* placement check */
function startDiag(){var steps=[],used=[],FT=['mcq','short','order','match','slider','angle','point','chips','graph','compass','multi','proof'],bf=function(q){return q.b!==undefined?q.b:LB[q.l]},k=0,seen={};
 ALL.forEach(function(t){var all=QS.filter(function(q){return q.t===t&&q.l<=2}).sort(function(a,b){return bf(a)-bf(b)});if(!all.length)return;var pick=null;
  for(var j=0;j<FT.length&&!pick;j++){var ty=FT[(k+j)%FT.length],c=all.filter(function(q){return q.type===ty&&used.indexOf(q.id)<0});if(c.length){pick=c[Math.floor(c.length*(.25+Math.random()*.5))];}}
  if(!pick)pick=all[Math.floor(all.length*(.25+Math.random()*.5))];used.push(pick.id);seen[pick.type]=(seen[pick.type]||0)+1;k++;steps.push({k:'try',it:mkItem(pick.id)})});
 /* make sure every available format is sampled at least twice; extra probes do not change topic placement */
 FT.forEach(function(ty){var need=2-(seen[ty]||0);if(need<=0)return;var c=QS.filter(function(q){return q.type===ty&&q.l<=2&&used.indexOf(q.id)<0});for(var i=0;i<need&&c.length;i++){var q=c.splice(Math.floor(Math.random()*c.length),1)[0];used.push(q.id);steps.push({k:'try',it:mkItem(q.id),probe:1})}});
 for(var i=steps.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),x=steps[i];steps[i]=steps[j];steps[j]=x}
 startSess({kind:'diag',title:'Placement check',steps:steps,nofb:true})}
var _fs=finishSess;finishSess=function(){var z=Z;var was=z&&z.fin;_fs.apply(this,arguments);if(z&&!was&&z.fin){if(z.kind==='diag'){S.dgr={};z.steps.forEach(function(s){if(s.k!=='try'||s.probe)return;var t=s.it.q.t,ok=!!s.it.ok;S.dgr[t]=ok?1:0;S.th[t]=ok?.9:-.9;S.ema[t]=ok?.8:.3;S.rn[t]=0});S.dg=today()}
  if(z.kind==='lesson'){S.ld[today()]=(S.ld[today()]||0)+1}save()}};
var _dr=drawResults;drawResults=function(top){_dr(top);var z=Z;if(!z||z.kind!=='diag'||!z.sumDone)return;var s=$('sess'),good=[],need=[];ALL.forEach(function(t){if(S.dgr&&S.dgr[t]===1)good.push(TOP[t].name);else if(S.dgr&&S.dgr[t]===0)need.push(TOP[t].name)});var b=s.querySelector('.s-body');if(b)b.insertAdjacentHTML('afterbegin','<div class="card"><h3>Your starting point</h3>'+(need.length?'<p><b>Start with:</b> '+need.slice(0,6).map(esc).join(' · ')+'</p>':'')+(good.length?'<p><b>Already strong:</b> '+good.slice(0,8).map(esc).join(' · ')+'</p>':'')+'</div>')};
})();

/* ===== format-aware personalization =====
   1. Every question format has a difficulty weight (a typed answer is harder than picking from choices at the same content level).
   2. For each student the engine learns, per format, whether they do better or worse than the model expects, with recent answers
      counting most so it follows the student as they change. That adjusts how hard each format is FOR THAT STUDENT.
   3. The picker samples every format early, re-checks formats now and then, and leans slightly toward formats that work for the student.
   Everything is stored on this device. Nothing is sent anywhere. */
var TYB={balance:.35,machine:.4,mistake:.45,lab:.5,fitc:.5,frbal:.55,lgate:.4,resnet:.45,barb:.35,xform:.5,ucirc:.45,sim:.4,tune:.5,swipe:.1,yn:0,mcq:0,multi:.25,chips:.2,match:.1,order:.25,slider:.3,angle:.35,point:.4,compass:.35,graph:.45,short:.6,proof:.8};
var FAM=[['Choosing',['mcq','multi'],'Picking the right answer from a list'],['Typing',['short','proof'],'Writing an answer or a proof step'],['Hands-on',['slider','angle','point','compass','graph'],'Dragging, tapping and measuring'],['Building',['order','match','chips'],'Putting things in order, matching, filling gaps']];
if(!S.fm)S.fm={};
function fmOf(t){return S.fm[t]||(S.fm[t]={n:0,res:0,last:0,ok:0})}
function fmAdj(t){var f=S.fm[t];if(!f||f.n<3)return 0;var sh=f.n/(f.n+4);return -Math.max(-.9,Math.min(.9,f.res*2.4))*sh}
function pBase(q){var th=S.th[q.t]||0,b=(q.b!==undefined?q.b:LB[q.l])+(TYB[q.type]||0);return 1/(1+Math.exp(-(th-b)))}
function pOK(t,q){var th=S.th[t]||0,b=(q.b!==undefined?q.b:LB[q.l])+(TYB[q.type]||0)+fmAdj(q.type);return 1/(1+Math.exp(-(th-b)))}
var _cuF=coachUpdate;coachUpdate=function(q,ok,helped){var p0=pBase(q);_cuF.apply(this,arguments);
 if(helped)return;var f=fmOf(q.type),a=f.n<10?.25:.12;f.res=f.n?f.res*(1-a)+((ok?1:0)-p0)*a:((ok?1:0)-p0)*a;f.n++;f.ok+=ok?1:0;f.last=dayN()};
/* picker: explore every format early, re-probe stale ones, lean slightly toward what works (never exclusively) */
var _cpF=coachPick;coachPick=function(o){
 if(o&&!o._st){var best=null,bs=-1e9,tg=o.target||TARGET,ex=o.exclude||[],last=o.last||[],d=dayN();
  var base=_cpF(o);if(!base)return base;
  /* with some probability, replace by the best item of an under-sampled or stale format at a similar topic mix */
  var cand=[],tot=0;Object.keys(TYB).forEach(function(t){var f=S.fm[t],n=f?f.n:0,age=f?d-f.last:99,w=n<3?.55:(age>12?.22:0);if(w>0&&QS.some(function(q){return q.type===t&&(!o.topics||o.topics.indexOf(q.t)>-1)}))cand.push([t,w])});
  var kind=Z&&Z.kind;if(kind==='diag'||kind==='mock')return base;
  if(cand.length&&Math.random()<Math.min(.5,cand.reduce(function(a,c){return Math.max(a,c[1])},0))){var pick=cand[Math.floor(Math.random()*cand.length)][0],
    id=_cpF(Object.assign({},o,{types:[pick],_st:1}));if(id)return id}
  /* mild preference for formats the student does well in */
  var fb=Object.keys(S.fm).filter(function(t){return S.fm[t].n>=6&&S.fm[t].res>.06});
  if(fb.length&&Math.random()<.22){var id2=_cpF(Object.assign({},o,{types:[fb[Math.floor(Math.random()*fb.length)]],_st:1}));if(id2)return id2}
  return base}
 return _cpF(o)};
/* "How you learn" summary */
function famStats(){return FAM.map(function(f){var n=0,w=0,ok=0;f[1].forEach(function(t){var x=S.fm[t];if(x){n+=x.n;w+=x.res*x.n;ok+=x.ok}});return{name:f[0],desc:f[2],n:n,res:n?w/n:0,acc:n?ok/n:0}})}
