document.addEventListener('input',function(e){var t=e.target;if(!STN.cur||!STN.st)return;if(t.classList&&t.classList.contains('si')){STN.st.in[t.dataset.i]=t.value;return}
 if(t.dataset&&t.dataset.r&&!STN.res&&STN.cur.range){STN.cur.range(STN.st,t.dataset.r,+t.value,t)}});
document.addEventListener('change',function(e){var t=e.target;if(!STN.cur||STN.res)return;if(t.dataset&&t.dataset.s&&STN.cur.act){if(STN.cur.act(STN.st,t.dataset.s,t.value,t)!==false)stnDraw()}});
var _rt=route;route=function(){_rt.apply(this,arguments);if(cur==='library'&&sub.lib==='stations'&&STN.cur&&STN.cur.after)STN.cur.after(STN.st)};

/* ===== Circuit Lab B stations, part 1 ===== */
function zig(x,y,w){var d='M'+x+' '+y+'h'+w*.15,s=w*.7/6,i;for(i=0;i<6;i++)d+='l'+s/2+' '+(i%2?'8':'-8')+'l'+s/2+' '+(i%2?'-8':'8');return '<path d="'+d.replace(/l([\d.]+) 8l([\d.]+) -8/g,'l$1 8l$2 -8')+'h'+w*.15+'"/>'}
function res(x,y,w,lab,val){return '<path d="M'+x+' '+y+'h'+w*.14+'l'+w*.06+' -9 '+w*.12+' 18 '+w*.12+' -18 '+w*.12+' 18 '+w*.12+' -18 '+w*.06+' 9h'+w*.14+'"/><text x="'+(x+w/2)+'" y="'+(y-14)+'" text-anchor="middle" font-size="11" fill="currentColor" stroke="none" font-weight="700">'+lab+'</text>'+(val?'<text x="'+(x+w/2)+'" y="'+(y+26)+'" text-anchor="middle" font-size="10.5" fill="currentColor" stroke="none">'+val+'</text>':'')}
function batt(x,y,h,lab){return '<path d="M'+x+' '+y+'v'+(h/2-5)+'M'+x+' '+(y+h/2+5)+'v'+(h/2-5)+'"/><path d="M'+(x-11)+' '+(y+h/2-5)+'h22" stroke-width="3"/><path d="M'+(x-6)+' '+(y+h/2+5)+'h12" stroke-width="3"/><text x="'+(x-18)+'" y="'+(y+h/2+4)+'" text-anchor="end" font-size="11" fill="currentColor" stroke="none" font-weight="700">'+lab+'</text><text x="'+(x+10)+'" y="'+(y+h/2-8)+'" font-size="10" fill="currentColor" stroke="none">+</text>'}
function cwrap(b,w,h){return '<svg viewBox="-34 -26 '+((w||300)+34)+' '+((h||150)+26)+'" class="itsvg" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="round">'+b+'</svg>'}
function lamp(x,y,lit,lab,r){r=r||13;return '<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="'+(lit>0?'rgba(255,200,40,'+Math.min(.95,.25+lit*.7)+')':'none')+'" '+(lit>0?'stroke="#e8a000" ':'')+'/><path d="M'+(x-r*.7)+' '+(y-r*.7)+'l'+r*1.4+' '+r*1.4+'M'+(x+r*.7)+' '+(y-r*.7)+'l'+(-r*1.4)+' '+r*1.4+'"/>'+(lab?'<text x="'+x+'" y="'+(y+r+14)+'" text-anchor="middle" font-size="11" fill="currentColor" stroke="none" font-weight="700">'+lab+'</text>':'')}
function meterBox(txt,sub){return '<div class="dmm"><div class="dm-d">'+txt+'</div><div class="dm-s">'+sub+'</div></div>'}

/* 1. Mystery resistor */
stnReg({id:'mystery',pack:'circ',topic:'circ',notes:'n6',title:'Mystery resistor',sub:'Voltmeter only',ic:'<path d="M3 12h4l2-5 4 10 2-5h6"/>',
 task:function(s){return 'Rx is unknown. You may only use the voltmeter. Known resistor: <b>'+eng(s.Rk)+'</b>, supply <b>'+s.Vs+' V</b>. Measure, then calculate Rx.'},
 gen:function(){var Rk=SP([100,220,330,470,1000,2200,4700]),pool=ESER.filter(function(v){return v>=47&&v<=22000&&v!==Rk&&v/Rk<=10&&Rk/v<=10});return {Vs:SP([5,6,9,12]),Rk:Rk,Rx:SP(pool),m:{},last:null}},
 view:function(s){var I=s.Vs/(s.Rk+s.Rx),h=cwrap(batt(40,30,80,s.Vs+' V')+'<path d="M40 30V14h60"/>'+res(100,14,70,'R known',eng(s.Rk))+res(170,14,70,'Rx','?')+'<path d="M240 14h30v116H40V110"/>',300,150);
  h+='<div class="mbtns">'+[['k','Across R known'],['x','Across Rx'],['b','Across battery']].map(function(b){return '<button class="btn sec sm'+(s.last===b[0]?' on':'')+'" data-a="m" data-v="'+b[0]+'">'+b[1]+'</button>'}).join('')+'</div>';
  h+=meterBox(s.last?(s.m[s.last]+' V'):'– – –','DC volts (20 V range)<br>'+(s.last?{k:'across R known',x:'across Rx',b:'across the battery'}[s.last]:'tap a button to place the probes'));
  h+='<div class="small mute" style="margin:6px 0">Readings: '+['k','x','b'].filter(function(k){return s.m[k]!==undefined}).map(function(k){return {k:'V(known)',x:'V(Rx)',b:'V(batt)'}[k]+' = '+s.m[k]+' V'}).join(' · ')+'</div>'+fld(s,'rx','Rx = ','Ω','e.g. 1500 or 1.5k');return h},
 act:function(s,a,v){if(a==='m'){var t={k:s.Vs*s.Rk/(s.Rk+s.Rx),x:s.Vs*s.Rx/(s.Rk+s.Rx),b:s.Vs*1.0};if(s.m[v]===undefined)s.m[v]=sig(t[v]*(1+SR(-.004,.004)),3);s.last=v}},
 check:function(s){var vk=s.m.k,vx=s.m.x,ans=pv(s.in.rx),ex=s.Rx,both=vk!==undefined&&vx!==undefined,calc=both?s.Rk*vx/vk:null,sc=0,L=[];
  L.push([both,both?'You measured both resistors.':'Measure the voltage across both resistors first.']);if(both)sc+=.2;
  var e=Math.abs(ans-ex)/ex;if(near(ans,ex,.04)){sc+=.8;L.push([true,'Rx ≈ '+eng(ex)+'. Your answer '+eng(ans)+' is within meter error.'])}else if(near(ans,ex,.1)){sc+=.4;L.push([false,'Close, but off by '+Math.round(e*100)+'%. The true Rx is '+eng(ex)+'.'])}else L.push([false,'The true Rx is '+eng(ex)+'.']);
  var I=s.Vs/(s.Rk+s.Rx);return {score:sc,lines:L,steps:['Rx and R known are in <b>series</b>, so the same current flows through both.','Current from the known resistor: I = V ÷ R = '+(vk!==undefined?vk:sig(s.Vs*s.Rk/(s.Rk+s.Rx)))+' V ÷ '+s.Rk+' Ω = '+sig(I*1000,3)+' mA.','Rx = V(Rx) ÷ I. Shortcut: Rx = R known × V(Rx) ÷ V(known) = '+s.Rk+' × '+(vx!==undefined?vx:sig(s.Vs*s.Rx/(s.Rk+s.Rx)))+' ÷ '+(vk!==undefined?vk:sig(s.Vs*s.Rk/(s.Rk+s.Rx)))+' = <b>'+eng(ex)+'</b> (nearest standard value).','Check: the two voltages should add up to the supply ('+s.Vs+' V). The bigger resistor always gets the bigger share.','Report with units and no more significant figures than your meter shows (3 here).']}},
 mats:'a 9 V battery or supply, two resistors (one marked), a breadboard, a digital multimeter, 4 jumper wires.',
 real:['Build the series loop on a breadboard: battery + → R known → Rx → battery −. Power off while you wire.','Set the meter to DC volts (V with the straight line). Red lead in V/Ω, black in COM.','Measure across each resistor by touching both ends. Write each reading with units.','Compute Rx = R known × V(Rx) ÷ V(known). Then measure Rx alone with the ohmmeter (power off, resistor removed) to check your answer.']});

/* 2. Series / parallel lab and target resistance */
function spReq(t,r){var a=r[0],b=r[1],c=r[2];return t==='s'?a+b+c:t==='p'?1/(1/a+1/b+1/c):a+(b*c)/(b+c)}
stnReg({id:'target',pack:'circ',topic:'circ',notes:'n6',title:'Create a target resistance',sub:'Series and parallel',ic:'<path d="M3 8h6l1-3 2 6 2-6 1 3h6M3 16h18"/>',
 task:function(s){return 'Build a combination of the three parts that equals <b>'+eng(s.T)+'</b> (within 3%). Check it with the ohmmeter <b>before</b> you apply power.'},
 gen:function(){var parts=[SP(ESER.filter(function(v){return v>=100&&v<=4700})),SP(ESER.filter(function(v){return v>=100&&v<=4700})),SP(ESER.filter(function(v){return v>=100&&v<=4700}))],t=SP(['s','p','m']),ord=parts.slice().sort(function(){return Math.random()-.5});return {parts:parts,T:sig(spReq(t,ord),3),topo:'s',pw:0,sawOff:false,Vs:9}},
 view:function(s){var R=spReq(s.topo,s.parts),I=s.pw?0:s.Vs/R,p=s.parts,h='';
  var b={s:batt(30,30,80,'')+'<path d="M30 30V16h25"/>'+res(55,16,60,'R1',eng(p[0]))+res(115,16,60,'R2',eng(p[1]))+res(175,16,60,'R3',eng(p[2]))+'<path d="M235 16h20v114H30V110"/>',
   p:batt(30,30,80,'')+'<path d="M30 30V16h60M90 16v0"/><path d="M60 16V16"/>'+['R1','R2','R3'].map(function(l,i){var x=70+i*70;return '<path d="M'+x+' 16v10"/><path d="M'+x+' 26v0"/>'+'<g transform="translate('+x+' 26) rotate(90)">'+res(0,0,60,'','')+'</g><text x="'+(x+14)+'" y="52" font-size="11" fill="currentColor" stroke="none" font-weight="700">'+l+'</text><text x="'+(x+14)+'" y="66" font-size="10" fill="currentColor" stroke="none">'+eng(p[i])+'</text><path d="M'+x+' 86v44"/>'}).join('')+'<path d="M70 16h140M70 130H30V110M70 130h140"/>',
   m:batt(30,30,80,'')+'<path d="M30 30V16h25"/>'+res(55,16,60,'R1',eng(p[0]))+'<path d="M115 16h40"/>'+[1,2].map(function(i){var y=i===1?16:70;return ''}).join('')+'<path d="M155 16V30M155 30h0"/><g transform="translate(155 30) rotate(90)">'+res(0,0,50,'','')+'</g><path d="M155 80v50"/><path d="M215 16V30"/><g transform="translate(215 30) rotate(90)">'+res(0,0,50,'','')+'</g><path d="M215 80v50"/><path d="M155 16h60M30 130h185"/><text x="170" y="56" font-size="11" fill="currentColor" stroke="none" font-weight="700">R2</text><text x="170" y="68" font-size="10" fill="currentColor" stroke="none">'+eng(p[1])+'</text><text x="230" y="56" font-size="11" fill="currentColor" stroke="none" font-weight="700">R3</text><text x="230" y="68" font-size="10" fill="currentColor" stroke="none">'+eng(p[2])+'</text>'};
  h+=cwrap(b[s.topo],270,145);
  h+='<div class="mbtns">'+[['s','All in series'],['p','All in parallel'],['m','R1 + (R2 ∥ R3)']].map(function(x){return '<button class="btn sec sm'+(s.topo===x[0]?' on':'')+'" data-a="t" data-v="'+x[0]+'">'+x[1]+'</button>'}).join('')+'<button class="btn sec sm" data-a="sw">Power: '+(s.pw?'OFF':'ON')+'</button></div>';
  h+='<div class="small mute">Parts: '+p.map(function(v,i){return 'R'+(i+1)+' = '+eng(v)}).join(' · ')+'. Tap R1, R2, R3 below to swap parts.</div><div class="mbtns">'+[[0,1],[1,2],[0,2]].map(function(q){return '<button class="btn sec sm" data-a="swap" data-v="'+q.join(',')+'">swap R'+(q[0]+1)+' ↔ R'+(q[1]+1)+'</button>'}).join('')+'</div>';
  h+=s.pw?meterBox(eng(R),'Ohmmeter · power OFF<br>total resistance between the battery terminals'):meterBox(sig(I*1000,3)+' mA','Power ON · '+s.Vs+' V supply<br>Total current. Switch power OFF to read resistance');
  return h},
 act:function(s,a,v){if(a==='t')s.topo=v;else if(a==='sw'){s.pw=s.pw?0:1;if(s.pw)s.sawOff=true}else if(a==='swap'){var q=v.split(',').map(Number),t=s.parts[q[0]];s.parts[q[0]]=s.parts[q[1]];s.parts[q[1]]=t}},
 check:function(s){var R=spReq(s.topo,s.parts),ok=near(R,s.T,.03),L=[[ok,'Your circuit is '+eng(R)+'. Target '+eng(s.T)+'.'],[s.sawOff,s.sawOff?'You measured with the power off.':'Always check resistance with the power off before applying power.']],sc=(ok?.75:0)+(s.sawOff?.25:0);
  var sol=null,P=s.parts,perms=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];['s','p','m'].forEach(function(t){perms.forEach(function(q){var r=spReq(t,q.map(function(i){return P[i]}));if(!sol&&near(r,s.T,.03))sol=[t,q]})});
  var nm={s:'all in series',p:'all in parallel',m:'R1 + (R2 ∥ R3)'};return {score:sc,lines:L,steps:['<b>Series:</b> add the values. R = R1 + R2 + R3. The total is larger than any single part.','<b>Parallel:</b> 1/R = 1/R1 + 1/R2 + 1/R3. For two parts, R = R1·R2 ÷ (R1+R2). The total is smaller than the smallest part.','<b>Mixed:</b> collapse the parallel pair first, then add the series part.',sol?'One working answer: '+nm[sol[0]]+' with R1 = '+eng(P[sol[1][0]])+', R2 = '+eng(P[sol[1][1]])+', R3 = '+eng(P[sol[1][2]])+' gives '+eng(spReq(sol[0],sol[1].map(function(i){return P[i]})))+'.':'Estimate first: a target below the smallest part needs parallel; above the largest needs series.','Verify with the ohmmeter on the unpowered circuit. Never measure resistance in a live circuit.']}},
 mats:'a breadboard, 3 resistors, a multimeter with an ohmmeter, jumper wires.',
 real:['Read each resistor’s color code and write its value and tolerance. Confirm with the ohmmeter (power off, part out of the circuit).','Decide series, parallel or mixed using the estimate rule: smaller than the smallest part means parallel; bigger than the largest means series.','Build it on the breadboard with no battery connected. Measure total resistance with the ohmmeter across the two ends.','Adjust until you are within the allowed error, then connect the battery and measure the current. Check I = V ÷ R.']});

/* 3. Troubleshoot a faulty circuit */
var FAULTS=[['open1','Lamp 1 has an open filament'],['open2','Lamp 2 has an open filament'],['opensw','The switch is open or faulty'],['wire','A loose wire (open connection)'],['short1','Lamp 1 is shorted'],['dead','The battery is dead']];
stnReg({id:'trouble',pack:'circ',topic:'circ',notes:'n6',title:'Troubleshoot a circuit',sub:'Find the fault',ic:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5M12 15.5v.5"/>',
 task:function(s){return 'A series circuit (battery, switch, two lamps, wire) is not working as it should. The switch is <b>ON</b>. Measure the voltage across parts to find the fault. Fewer measurements is better.'},
 gen:function(){return {f:SP(FAULTS)[0],Vs:SP([6,9,12]),m:{},n:0,last:null}},
 view:function(s){var els=[['b','Battery'],['sw','Switch'],['l1','Lamp 1'],['l2','Lamp 2'],['w','Wire']],f=s.f,lit1=f==='short1'?0:0,lit2=f==='short1'?1:0;
  var d=cwrap(batt(30,30,80,'')+'<path d="M30 30V16h30"/><path d="M60 16H82"/><circle cx="60" cy="16" r="2.5"/><circle cx="82" cy="16" r="2.5"/><path d="M82 16h40"/>'+lamp(135,16,0,'L1',11)+'<path d="M146 16h30"/>'+lamp(190,16,lit2,'L2',11)+'<path d="M201 16h50v114H30V110"/><text x="60" y="44" font-size="10" fill="currentColor" stroke="none">switch ON</text><text x="205" y="72" font-size="10" fill="currentColor" stroke="none">wire</text>',280,145);
  d+=(f==='short1'?'<p class="small mute">Lamp 2 is glowing. Lamp 1 is dark.</p>':'<p class="small mute">Both lamps are dark.</p>')+'<div class="mbtns">'+els.map(function(e){return '<button class="btn sec sm'+(s.last===e[0]?' on':'')+'" data-a="m" data-v="'+e[0]+'">'+e[1]+'</button>'}).join('')+'</div>'+meterBox(s.last?s.m[s.last]+' V':'– – –','DC volts · probes across '+(s.last?els.filter(function(e){return e[0]===s.last})[0][1].toLowerCase():'(tap a part)'));
  d+='<div class="small mute" style="margin:6px 0">'+Object.keys(s.m).map(function(k){return els.filter(function(e){return e[0]===k})[0][1]+': '+s.m[k]+' V'}).join(' · ')+'</div><label class="fld"><span>Diagnosis</span><select data-s="dx">'+['<option value="">Choose…</option>'].concat(FAULTS.map(function(x){return '<option value="'+x[0]+'"'+(s.dx===x[0]?' selected':'')+'>'+x[1]+'</option>'})).join('')+'</select></label>';return d},
 act:function(s,a,v){if(a==='m'){var f=s.f,V=s.Vs,t={b:f==='dead'?.2:V,sw:f==='opensw'?V:0,l1:f==='open1'?V:f==='short1'?0:0,l2:f==='open2'?V:f==='short1'?V:0,w:f==='wire'?V:0};if(s.m[v]===undefined){s.m[v]=sig(t[v]*(1+SR(-.01,.01)),3);s.n++}s.last=v}else if(a==='dx')s.dx=v},
 check:function(s){var ok=s.dx===s.f,nm=FAULTS.filter(function(x){return x[0]===s.f})[0][1],eff=s.n<=3,sc=(ok?.8:0)+(ok&&eff?.2:0);return {score:sc,lines:[[ok,ok?'Correct: '+nm+'.':'The fault was: '+nm+'.'],[ok&&eff,'You used '+s.n+' measurement'+(s.n===1?'':'s')+(eff?'. Efficient.':'. Aim for three or fewer.')]],steps:['Turn power off and look first: loose, reversed or missing parts.','In a <b>series</b> loop the same current flows everywhere, so a break stops all of it.','The part that shows the <b>full source voltage</b> ('+s.Vs+' V) across it is the open part: all the voltage drops across the break.','A part that reads <b>0 V</b> while others read the full voltage is shorted (its twin gets the whole supply and glows brighter).','If the battery itself reads near 0 V, it is dead or overloaded. Replace it before looking further.','Here: '+nm+'.']}},
 mats:'a battery, a switch, two small lamps (or LEDs with resistors), wires, a multimeter, one spare lamp.',
 real:['Have a partner secretly break the circuit: loosen one wire, swap in a burnt lamp, or short across one lamp with a wire.','Power off. Inspect for loose, reversed or missing parts.','Power on. Measure DC voltage across the battery first, then across each part. Write each reading.','The full-supply reading marks the open part. A zero reading across a lamp while the other is bright marks a short. Fix it and retest.']});

/* 4. LED resistor design */
function ledI(s){return Math.max(0,(s.Vs-s.c[1])/ESER[s.idx])*1000}
function ledSvg(s){var R=ESER[s.idx],I=ledI(s),glow=Math.min(1,I/25),burn=I>25;return cwrap(batt(30,30,80,s.Vs+' V')+'<path d="M30 30V16h50"/>'+res(80,16,80,'R',eng(R))+'<path d="M160 16h40"/><path d="M200 5v22l18-11zM218 5v22" '+(burn?'stroke="#999"':'')+'/><circle cx="209" cy="16" r="'+(burn?3:8+glow*14)+'" fill="'+(burn?'#555':s.c[2])+'" fill-opacity="'+(burn?.9:.15+glow*.55)+'" stroke="none"/><path d="M218 16h30v114H30V110"/><text x="209" y="48" text-anchor="middle" font-size="10" fill="currentColor" stroke="none">'+s.c[0]+' LED</text>',270,145)}
function ledMeter(s){var I=ledI(s),burn=I>25;return meterBox(sig(I,3)+' mA',burn?'<b style="color:#ff9aa5">LED burned out!</b> Too much current':I<s.If*.7?'Dim: not enough current':'Current through the LED')}
var LEDC=[['red',1.9,'#ff3b30'],['yellow',2.1,'#ffd60a'],['green',2.2,'#34c759'],['blue',3.0,'#3b82f6'],['white',3.1,'#f2f2f7']];
stnReg({id:'led',pack:'circ',topic:'diode',notes:'n9',title:'LED and resistor',sub:'Pick the series resistor',ic:'<path d="M4 12h5l5-6v12l-5-6M14 12h6M17 4l3 3M20 4l-3 3"/>',
 task:function(s){return 'Power a <b>'+s.c[0]+'</b> LED (forward voltage <b>'+s.c[1]+' V</b>) from a <b>'+s.Vs+' V</b> supply at <b>'+s.If+' mA</b>. The LED is damaged above 25 mA.'},
 gen:function(){var c=SP(LEDC);return {c:c,Vs:SP(c[1]>2.5?[5,9,12]:[5,9,12]),If:SP([10,12,15,20]),idx:ESER.indexOf(330)}},
 view:function(s){return '<div id="ledsvg">'+ledSvg(s)+'</div><div class="rng"><span>Resistor</span><input type="range" min="0" max="'+(ESER.length-1)+'" value="'+s.idx+'" data-r="idx"'+(s.done?' disabled':'')+'><b id="rv">'+eng(ESER[s.idx])+'</b></div><div id="ledm">'+ledMeter(s)+'</div>'+fld(s,'rc','Calculated R = ','Ω','(Vs − Vf) ÷ I')},
 range:function(s,k,v){s.idx=v;$('rv').textContent=eng(ESER[v]);$('ledsvg').innerHTML=ledSvg(s);$('ledm').innerHTML=ledMeter(s)},
 check:function(s){var Rc=(s.Vs-s.c[1])/(s.If/1000),R=ESER[s.idx],I=(s.Vs-s.c[1])/R*1000,a=pv(s.in.rc),ok1=near(a,Rc,.05),ok2=I<=25&&I>=s.If*.75&&I<=s.If*1.15;return {score:(ok1?.5:0)+(ok2?.5:0),lines:[[ok1,ok1?'Calculated R is right: '+eng(Rc)+'.':'R = (Vs − Vf) ÷ I = ('+s.Vs+' − '+s.c[1]+') ÷ '+(s.If/1000)+' A = '+eng(Rc)+'.'],[ok2,ok2?'Your chosen '+eng(R)+' gives '+sig(I,3)+' mA. Safe and bright.':'Your chosen '+eng(R)+' gives '+sig(I,3)+' mA. Aim for about '+s.If+' mA and never above 25 mA.']],steps:['The resistor must drop the voltage the LED does not use: '+s.Vs+' V − '+s.c[1]+' V = '+sig(s.Vs-s.c[1])+' V.','The same current flows through the LED and resistor (series), so use Ohm’s law on the resistor: R = V ÷ I.','R = '+sig(s.Vs-s.c[1])+' V ÷ '+(s.If/1000)+' A = <b>'+eng(Rc)+'</b>.','Pick the nearest standard value that keeps the current at or below the target. Rounding <b>up</b> is the safe choice.','Check the resistor power: P = I²R = '+sig(Math.pow(s.If/1000,2)*Rc*1000,2)+' mW, so a ¼ W resistor is plenty.','Check polarity: the longer lead (anode) toward the positive side. An LED only conducts one way.']}},
 mats:'a 5 V supply or 9 V battery, an LED, assorted resistors, a breadboard, a multimeter.',
 real:['Look up the LED’s forward voltage and safe current (or use the table in your notes).','Calculate R = (Vs − Vf) ÷ I and pick the next higher standard resistor.','Build: supply + → resistor → LED long lead (anode) → LED short lead → supply −. Keep power off while wiring.','Power on. Measure the voltage across the resistor and use I = V ÷ R to confirm the current. A dim LED means R is too big; a hot LED means it is too small.']});

/* ===== Circuit Lab B stations, part 2 ===== */
/* 5. Logic from a truth table */
var LOPS=['AND','OR','XOR','NAND','NOR'],LIN=['A','A′','B','B′','C','C′'];
function lop(o,a,b){return o==='AND'?a&b:o==='OR'?a|b:o==='XOR'?a^b:o==='NAND'?1-(a&b):1-(a|b)}
function lin(x,A,B,C){var v=x[0]==='A'?A:x[0]==='B'?B:C;return x.length>1?1-v:v}
function lgY(g,A,B,C){return lop(g.o2,lop(g.o1,lin(g.x1,A,B,C),lin(g.x2,A,B,C)),lin(g.x3,A,B,C))}
stnReg({id:'logic',pack:'circ',topic:'logic',notes:'n10',title:'Logic from a truth table',sub:'Build the gates',ic:'<path d="M4 6h7a6 6 0 010 12H4zM1 9h3M1 15h3M17 12h5"/>',
 task:function(s){return 'Make <b>Your Y</b> match the <b>target Y</b> in every row. Pick inputs (A′ means NOT A) and gate types for Y = (X1 gate1 X2) gate2 X3.'},
 gen:function(){var g,n=0;do{g={x1:SP(LIN),x2:SP(LIN),x3:SP(LIN),o1:SP(LOPS),o2:SP(LOPS)};var c=0;for(var i=0;i<8;i++)c+=lgY(g,i>>2&1,i>>1&1,i&1);n++}while((c<2||c>6||g.x1[0]===g.x2[0])&&n<50);return {t:g,u:{x1:'A',x2:'B',x3:'C',o1:'AND',o2:'OR'}}},
 view:function(s){var u=s.u,sel=function(k,list){return '<select data-s="'+k+'">'+list.map(function(x){return '<option'+(u[k]===x?' selected':'')+'>'+x+'</option>'}).join('')+'</select>'},h='<div class="lgb">Y = ( '+sel('x1',LIN)+' '+sel('o1',LOPS)+' '+sel('x2',LIN)+' ) '+sel('o2',LOPS)+' '+sel('x3',LIN)+'</div><table class="tt"><tr><th>A</th><th>B</th><th>C</th><th>Target Y</th><th>Your Y</th><th></th></tr>';
  for(var i=0;i<8;i++){var A=i>>2&1,B=i>>1&1,C=i&1,t=lgY(s.t,A,B,C),y=lgY(u,A,B,C);h+='<tr class="'+(t===y?'m':'x')+'"><td>'+A+'</td><td>'+B+'</td><td>'+C+'</td><td><b>'+t+'</b></td><td>'+y+'</td><td>'+(t===y?'✓':'✗')+'</td></tr>'}return h+'</table>'},
 act:function(s,a,v){s.u[a]=v},
 check:function(s){var m=0,mins=[];for(var i=0;i<8;i++){var A=i>>2&1,B=i>>1&1,C=i&1;if(lgY(s.t,A,B,C)===lgY(s.u,A,B,C))m++;if(lgY(s.t,A,B,C))mins.push((A?'A':'A′')+'·'+(B?'B':'B′')+'·'+(C?'C':'C′'))}
  var t=s.t;return {score:m/8,lines:[[m===8,m+' of 8 rows match.']],steps:['List the rows where the target Y is 1: '+mins.join(' + ')+'.','Each row is an AND term: use the letter if the input is 1 and the NOT version if it is 0.','OR the terms together, then simplify by factoring or using De Morgan: break the bar, flip the operator.','One working build: Y = ('+t.x1+' '+t.o1+' '+t.x2+') '+t.o2+' '+t.x3+'.','Verify every row, including the ones that should be 0. One wrong row means the expression is wrong.']}},
 mats:'a printed truth table, 7400 (NAND), 7408 (AND), 7432 (OR), 7404 (NOT) chips or a logic simulator, a breadboard, LEDs with resistors, a 5 V supply.',
 real:['Write the truth table and mark the rows where Y = 1.','Write the AND term for each of those rows, OR them, and simplify.','Choose gates for the simplified form. A·B′ needs a NOT on B feeding an AND.','Wire it, apply every input combination with jumper wires to 5 V or ground, and write down Y from the LED. Compare each row with the table.']});

/* 6. Power and energy from labels */
stnReg({id:'power',pack:'circ',topic:'virpe',notes:'n5',title:'Charger and battery',sub:'Power and energy',ic:'<path d="M13 3L5 14h6l-1 7 8-11h-6z"/>',
 task:function(s){return 'A USB charger label lists <b>'+s.lv.map(function(l){return l[0]+' V / '+l[1]+' A'}).join(', ')+'</b>. A battery is rated <b>'+s.bv+' V, '+s.mah+' mAh</b>. Charging is <b>'+s.eff+'%</b> efficient.'},
 gen:function(){var lv=SP([[[5,3],[9,2],[12,1.5]],[[5,2],[9,1.67],[15,3]],[[5,2.4],[9,2],[12,2]]]);return {lv:lv,bv:SP([3.7,7.4,11.1]),mah:SP([2000,3000,5000,6000]),eff:SP([80,85,90])}},
 view:function(s){return ''+fld(s,'p1','Power at the highest-voltage level ('+s.lv[2][0]+' V / '+s.lv[2][1]+' A)','W')+fld(s,'wh','Battery energy','Wh')+fld(s,'hr','Time to fill the battery from empty at the '+s.lv[2][0]+' V level','hours')},
 check:function(s){var P=s.lv[2][0]*s.lv[2][1],Wh=s.bv*s.mah/1000,T=Wh/(P*s.eff/100),a=[pv(s.in.p1),pv(s.in.wh),pv(s.in.hr)],t=[P,Wh,T],nm=['Power','Battery energy','Charge time'],un=['W','Wh','h'],sc=0,L=[];
  for(var i=0;i<3;i++){var ok=near(a[i],t[i],.02);if(ok)sc+=1/3;L.push([ok,nm[i]+': '+sig(t[i],3)+' '+un[i]+(ok?'':' (you wrote '+(isFinite(a[i])?sig(a[i],3):'nothing')+')')])}
  return {score:sc,lines:L,steps:['Power in watts: P = V × I = '+s.lv[2][0]+' V × '+s.lv[2][1]+' A = <b>'+sig(P,3)+' W</b>.','Battery energy: Wh = V × Ah. Convert mAh to Ah first: '+s.mah+' mAh = '+(s.mah/1000)+' Ah. Wh = '+s.bv+' × '+(s.mah/1000)+' = <b>'+sig(Wh,3)+' Wh</b>.','Usable charging power = '+sig(P,3)+' W × '+s.eff+'% = '+sig(P*s.eff/100,3)+' W.','Time = energy ÷ power = '+sig(Wh,3)+' Wh ÷ '+sig(P*s.eff/100,3)+' W = <b>'+sig(T,3)+' h</b>.','Sanity check: units cancel to hours. A bigger charger should give a shorter time.']}},
 mats:'a USB charger or battery with a readable label, a calculator.',
 real:['Find the label on a phone charger and a battery. Copy every V and A pair.','Compute P = V × I for each pair.','Compute battery energy Wh = V × Ah (mAh ÷ 1000).','Estimate charging time = Wh ÷ (W × efficiency). Compare with how long the device really takes.']});

/* 7. Three-way switch */
function twF(o,a,b){return o==='A'?(a===b?1:0):o==='B'?(a!==b?1:0):o==='C'?(a===0&&b===0?1:0):0}
function twSvg(o,a,b){var y1=a?60:30,y2=b?60:30,on=twF(o,a,b),w=o==='A'?'<path d="M40 30H95M40 60H95"/>':o==='B'?'<path d="M40 30L95 60M40 60L95 30"/>':o==='C'?'<path d="M40 30H95"/>':'';
 return cwrap('<path d="M2 45h8"/><circle cx="10" cy="45" r="2.5"/><path d="M10 45L40 '+y1+'"/><circle cx="40" cy="30" r="2.5"/><circle cx="40" cy="60" r="2.5"/>'+w+'<circle cx="95" cy="30" r="2.5"/><circle cx="95" cy="60" r="2.5"/><path d="M125 45L95 '+y2+'"/><circle cx="125" cy="45" r="2.5"/><path d="M125 45h6"/>'+lamp(148,45,on,'',12)+'<text x="25" y="20" font-size="10" fill="currentColor" stroke="none">S1</text><text x="108" y="20" font-size="10" fill="currentColor" stroke="none">S2</text>',165,80)}
stnReg({id:'threeway',pack:'circ',topic:'circ',notes:'n8',title:'Three-way switch',sub:'Control a lamp from two places',ic:'<path d="M3 17l7-9M10 8h4M14 17l7-9M3 17h3M14 17h3"/>',
 task:function(s){return 'Flip S1 and S2. Which wirings let <b>either</b> switch toggle the lamp from any position? (Flipping one switch must always change the lamp.) Select every wiring that works.'},
 gen:function(){return {p1:0,p2:0,pick:{}}},
 view:function(s){var h='<div class="mbtns"><button class="btn sec sm" data-a="f1">Flip S1 (now '+(s.p1?'down':'up')+')</button><button class="btn sec sm" data-a="f2">Flip S2 (now '+(s.p2?'down':'up')+')</button></div><div class="tw">';['A','B','C','D'].forEach(function(o){h+='<div class="twc'+(s.pick[o]?' sel':'')+'"><b>Wiring '+o+'</b>'+twSvg(o,s.p1,s.p2)+'<button class="btn sec sm" data-a="pk" data-v="'+o+'">'+(s.pick[o]?'✓ Works':'Mark as working')+'</button></div>'});return h+'</div>'},
 act:function(s,a,v){if(a==='f1')s.p1=1-s.p1;else if(a==='f2')s.p2=1-s.p2;else if(a==='pk')s.pick[v]=!s.pick[v]},
 check:function(s){var good={A:1,B:1,C:0,D:0},sc=0,L=[],txt={A:'Travelers wired straight across (T1↔T1, T2↔T2). Works.',B:'Travelers crossed (T1↔T2, T2↔T1). Works.',C:'Only one traveler wired. Fails: when S1 or S2 sits on the missing wire the lamp is dead.',D:'No travelers. The lamp can never light.'};['A','B','C','D'].forEach(function(o){var ok=!!s.pick[o]===!!good[o];if(ok)sc+=.25;L.push([ok,'Wiring '+o+': '+txt[o]])});
  return {score:sc,lines:L,steps:['A three-way setup has two SPDT switches. Each has a <b>common</b> terminal and two <b>traveler</b> terminals.','Switch 1’s common connects to the source. Switch 2’s common connects to the lamp.','Join the two travelers between the switches with two wires. Either straight or crossed works; the only difference is which positions are “on”.','Rule check: flip any one switch and the lamp must change. That needs <b>two</b> traveler wires, so a path exists in exactly one of the two positions at a time.','Test all four switch positions: up/up, up/down, down/up, down/down. The lamp must be ON in two of them and OFF in the other two.']}},
 mats:'two SPDT switches (three-way switches), a battery or low-voltage supply, a lamp, five wires.',
 real:['Mark the common terminal on each switch (usually the darker screw or labelled COM).','Connect battery + to switch 1 common. Connect switch 2 common to the lamp, then the lamp to battery −.','Join the two traveler terminals of switch 1 to the two of switch 2 with two wires.','Test all four positions and write the table. Swap two traveler wires and see that the lamp logic flips but still toggles from both switches.']});

/* 8. Breadboard and meter basics */
var DIALS=[['dcv','DC volts (V with a straight line)'],['acv','AC volts (V with a wave)'],['ohm','Resistance (Ω)'],['dca','DC current (A or mA)'],['cont','Continuity (beep)']],PORTS=[['vo','V Ω (voltage and resistance jack)'],['ma','mA jack'],['a10','10 A jack']];
var SCEN=[['Measure the voltage of a 9 V battery.','dcv','vo'],['Measure the resistance of a resistor taken out of the circuit.','ohm','vo'],['Measure the current through a small lamp. The meter goes in series.','dca','ma'],['Check that a wire has no break (beeps if connected).','cont','vo'],['Measure the AC voltage of a small transformer output.','acv','vo']];
stnReg({id:'board',pack:'circ',topic:'hands',notes:'n6',title:'Breadboard and meter',sub:'Which holes connect?',ic:'<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M7 10h.01M11 10h.01M15 10h.01M7 14h.01M11 14h.01M15 14h.01"/>',
 task:function(s){return 'Part 1: tap every hole that is <b>electrically connected</b> to the red-ringed hole. Part 2: set up the meter for the job.'},
 gen:function(){var rail=Math.random()<.35,split=Math.random()<.5,top=Math.random()<.5,col=SI(1,10),row=SP(top?['a','b','c','d','e']:['f','g','h','j','i']);var sc=SP(SCEN);return {rail:rail,split:split,col:col,row:row,top:top,rrow:SP([0,1]),sel:{},sc:sc,dial:'',port:''}},
 view:function(s){var h='<svg viewBox="0 0 330 190" class="itsvg bb" fill="none">',X=function(c){return 28+c*24},rows=['a','b','c','d','e','f','g','h','i','j'];
  function hole(id,x,y,hl){return '<circle data-a="h" data-v="'+id+'" cx="'+x+'" cy="'+y+'" r="7.5" class="hole'+(s.sel[id]?' on':'')+(hl?' tgt':'')+'"/>'}
  for(var r=0;r<2;r++){h+='<text x="6" y="'+(16+r*14)+'" font-size="9" fill="currentColor">'+(r?'−':'+')+'</text>';for(var c=1;c<=12;c++)h+=hole('r'+r+'-'+c,X(c-1)+12,12+r*14,s.rail&&s.rrow===r&&c===s.col+0&&true)}
  if(s.split)h+='<path d="M163 6v32" stroke="#e11" stroke-dasharray="2 2"/><text x="166" y="48" font-size="8" fill="#e11">split</text>';
  rows.forEach(function(rw,ri){var y=62+ri*12.5+(ri>4?10:0);h+='<text x="6" y="'+(y+3)+'" font-size="9" fill="currentColor">'+rw+'</text>';for(var c=1;c<=12;c++)h+=hole(rw+c,X(c-1)+12,y,!s.rail&&rw===s.row&&c===s.col)});
  h+='<rect x="26" y="127" width="290" height="6" rx="2" fill="currentColor" opacity=".25"/><text x="170" y="149" text-anchor="middle" font-size="8" fill="currentColor" opacity=".6">center gap</text>';
  h+='</svg><div class="small mute">Selected: '+Object.keys(s.sel).filter(function(k){return s.sel[k]}).length+' holes. The ringed hole is not counted.</div>';
  h+='<div class="stn-sub"><b>Part 2:</b> '+s.sc[0]+'</div><label class="fld"><span>Dial position</span><select data-s="dial"><option value="">Choose…</option>'+DIALS.map(function(d){return '<option value="'+d[0]+'"'+(s.dial===d[0]?' selected':'')+'>'+d[1]+'</option>'}).join('')+'</select></label><label class="fld"><span>Red lead goes in</span><select data-s="port"><option value="">Choose…</option>'+PORTS.map(function(d){return '<option value="'+d[0]+'"'+(s.port===d[0]?' selected':'')+'>'+d[1]+'</option>'}).join('')+'</select></label><p class="small mute">The black lead always goes in COM.</p>';return h},
 act:function(s,a,v){if(a==='h')s.sel[v]=!s.sel[v];else if(a==='dial')s.dial=v;else if(a==='port')s.port=v;return a==='h'},
 after:function(s){},
 check:function(s){var want={},c=s.col;if(s.rail){for(var k=1;k<=12;k++){if(k===c)continue;if(s.split&&((k<=6)!==(c<=6)))continue;want['r'+s.rrow+'-'+k]=1}}else{(s.top?['a','b','c','d','e']:['f','g','h','i','j']).forEach(function(r){if(r!==s.row)want[r+c]=1})}
  var got=Object.keys(s.sel).filter(function(k){return s.sel[k]}),hit=got.filter(function(k){return want[k]}).length,wrong=got.length-hit,tot=Object.keys(want).length,p1=Math.max(0,(hit-wrong)/tot),dOK=s.dial===s.sc[1],pOK=s.port===s.sc[2];
  return {score:p1*.6+(dOK?.25:0)+(pOK?.15:0),lines:[[p1===1,'Holes: '+hit+' of '+tot+' correct'+(wrong?', '+wrong+' wrong':'')+'.'],[dOK,'Dial: '+DIALS.filter(function(d){return d[0]===s.sc[1]})[0][1]+'.'],[pOK,'Red lead: '+PORTS.filter(function(d){return d[0]===s.sc[2]})[0][1]+'.']],steps:s.rail?['Power rails run the <b>full length</b> of the board, but many boards <b>split</b> the rail in the middle. A split means the left and right halves are <b>not</b> connected.','Here the rail '+(s.split?'is split, so only the same half is connected.':'is not split, so all 11 other holes are connected.'),'Always test a rail with the meter’s continuity mode before trusting it.']:['Each short column of <b>five holes</b> (a–e, or f–j) is connected.','The center gap breaks the board: column '+c+' in a–e is <b>not</b> connected to column '+c+' in f–j.','So the hole is connected to the other four in its half-column ('+(s.top?'a–e':'f–j')+').','Meter: '+s.sc[0]+' Set the dial to '+DIALS.filter(function(d){return d[0]===s.sc[1]})[0][1]+' and plug red into '+PORTS.filter(function(d){return d[0]===s.sc[2]})[0][1]+'. Current is the only measurement that goes <b>in series</b> and uses the mA or 10 A jack.']}},
 mats:'a solderless breadboard, a multimeter, a few jumper wires, a 9 V battery.',
 real:['Put a jumper wire from one hole to another in the same short column and use continuity mode: it beeps. Try across the center gap: no beep.','Test each power rail end to end with continuity. Mark any rail that is split.','Practice meter setup for five jobs: battery voltage, resistor value, series current, wire continuity, AC voltage. Say the dial position and red-lead jack out loud before touching anything.','Never put the meter in current mode across a battery or supply. That is a short circuit.']});

/* 9. Electromagnet */
var MAG=[['air core',1],['steel nail',20],['soft iron bolt',60]];
stnReg({id:'magnet',pack:'circ',topic:'mag',notes:'n12',title:'Electromagnet',sub:'Lift the paper clips',ic:'<path d="M5 5v8a7 7 0 0014 0V5M5 5h4M15 5h4"/>',
 task:function(s){return 'Wind the coil to lift <b>at least '+s.T+' paper clips</b>. Limits: up to <b>'+s.maxN+' turns</b> and <b>'+s.maxB+' battery(ies)</b> (1.5 V each). Record a trial when you are happy.'},
 gen:function(){var maxB=SP([2,3]),maxN=SP([40,60,100]),mc=magClips({N:maxN,B:maxB,core:2});return {T:SI(Math.max(2,Math.round(mc*.4)),Math.max(3,Math.floor(mc*.85))),maxB:maxB,maxN:maxN,N:20,B:1,core:0,rec:[]}},
 view:function(s){return '<div id="mgv">'+magView(s)+'</div><div class="rng"><span>Turns</span><input type="range" min="10" max="100" step="10" value="'+s.N+'" data-r="N"'+(s.done?' disabled':'')+'><b id="mn">'+s.N+'</b></div><div class="rng"><span>Batteries</span><input type="range" min="1" max="3" step="1" value="'+s.B+'" data-r="B"'+(s.done?' disabled':'')+'><b id="mb">'+s.B+'</b></div><div class="mbtns">'+MAG.map(function(m,i){return '<button class="btn sec sm'+(s.core===i?' on':'')+'" data-a="core" data-v="'+i+'">'+m[0]+'</button>'}).join('')+'</div><div class="mbtns"><button class="btn sec sm" data-a="rec">Record trial</button></div><div class="small mute">'+(s.rec.length?'Trials: '+s.rec.map(function(r){return r.N+' turns, '+r.B+' batt, '+MAG[r.core][0]+' → '+r.c+' clips'}).join(' · '):'No trials recorded yet.')+'</div>'},
 range:function(s,k,v){s[k]=v;$('mn').textContent=s.N;$('mb').textContent=s.B;$('mgv').innerHTML=magView(s)},
 act:function(s,a,v){if(a==='core'){s.core=+v;return true}if(a==='rec'){s.rec.push({N:s.N,B:s.B,core:s.core,c:magClips(s)});return true}return false},
 check:function(s){var c=magClips(s),inL=s.N<=s.maxN&&s.B<=s.maxB,ok=c>=s.T&&inL,tr=s.rec.length>=2;return {score:(c>=s.T?.5:0)+(inL?.25:0)+(tr?.25:0),lines:[[c>=s.T,'Your setup lifts '+c+' clip'+(c===1?'':'s')+' (needed '+s.T+').'],[inL,inL?'You stayed within the limits.':'You exceeded the turn or battery limit.'],[tr,tr?'You compared at least two trials.':'Change one variable at a time and record at least two trials.']],steps:['Strength depends on <b>current</b>, <b>number of turns</b> and the <b>core</b>: more turns, more current, and a soft iron core make it stronger.','Test <b>one variable at a time</b> (same battery, double the turns; then same turns, add a battery). Otherwise you cannot tell what helped.','A soft iron core concentrates the magnetic field far more than an air core, so it is the biggest single improvement.','Do not exceed the battery limit: a short, thick coil on a big supply gets hot and drains the battery.','Always disconnect the battery between trials.']}},
 mats:'an iron bolt or large nail, 3–4 m of insulated magnet wire, 1–3 AA batteries in a holder, paper clips, a switch.',
 real:['Wrap 20 turns around the bolt, all in the same direction, leaving 15 cm of bare wire at each end (sand the enamel).','Connect one battery and count how many clips hang from the tip. Disconnect between trials.','Double the turns to 40 with the same battery. Record. Then add a second battery with 40 turns. Record.','Replace the iron bolt with a wooden dowel or no core and compare. Make a table: turns, batteries, core, clips.']});
function magClips(s){var I=s.B*0.6;return Math.floor(0.03*s.N*I*MAG[s.core][1]/10)}
function magView(s){var c=magClips(s),h='<div class="small"><b>'+c+'</b> clips lifted · current ≈ '+sig(s.B*0.6,2)+' A</div>',b='';for(var i=0;i<Math.min(c,12);i++)b+='<rect x="'+(130+i%4*9)+'" y="'+(86+Math.floor(i/4)*9)+'" width="6" height="12" rx="2" stroke="#778"/>';
 var coil='';for(var j=0;j<Math.min(14,Math.round(s.N/8));j++)coil+='<path d="M'+(95+j*6)+' 62l3 -10M'+(95+j*6)+' 62l3 10" stroke="#c27a2c" stroke-width="2.2"/>';
 return h+cwrap('<rect x="'+(s.core?90:92)+'" y="54" width="'+(s.core?90:86)+'" height="16" rx="'+(s.core===2?2:7)+'" fill="'+(s.core===2?'#8a909c':s.core===1?'#b9bec8':'none')+'" stroke="#778"/>'+coil+(c?'<path d="M135 72v12" stroke="#aab"/>':'')+b+'<text x="8" y="20" font-size="10" fill="currentColor" stroke="none">'+s.N+' turns · '+s.B+' × 1.5 V · '+MAG[s.core][0]+'</text>',280,130)}

/* ===== Meteorology stations, part 1: station model, METAR, scales ===== */
function msel(s,k,label,list,ph){return '<label class="fld"><span>'+label+'</span><select data-s="'+k+'"'+(s.done?' disabled':'')+'><option value="">'+(ph||'Choose…')+'</option>'+list.map(function(x){var v=Array.isArray(x)?x[0]:x,t=Array.isArray(x)?x[1]:x;return '<option value="'+esc(v)+'"'+(s.in[k]===v?' selected':'')+'>'+esc(t)+'</option>'}).join('')+'</select></label>'}
function mset(s,a,v){s.in[a]=v;return false}
function mwarn(ok,txt){return [ok,txt]}
var COMPASS=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
function comp(d){return COMPASS[Math.round(d/22.5)%16]}

/* ---- station model ---- */
var SKY=[['clear','Clear (0/8)',0],['few','Few (1–2/8)',.25],['sct','Scattered (3–4/8)',.5],['bkn','Broken (5–7/8)',.75],['ovc','Overcast (8/8)',1]];
function barbSvg(cx,cy,dir,spd){if(spd<3)return '<circle cx="'+cx+'" cy="'+cy+'" r="17" fill="none" stroke="currentColor"/>';var th=dir*Math.PI/180,ux=Math.sin(th),uy=-Math.cos(th),vx=-uy,vy=ux,L=56,d='M'+cx+' '+cy+'L'+(cx+ux*L)+' '+(cy+uy*L),n=Math.round(spd/5)*5,p=Math.floor(n/50),f=Math.floor((n%50)/10),h=(n%10)?1:0,pos=L,out=d;
 function pt(o,k){return [cx+ux*o+vx*k,cy+uy*o+vy*k]}
 for(var i=0;i<p;i++){var a=pt(pos,0),b=pt(pos,14),c=pt(pos-8,0);out+='M'+a[0]+' '+a[1]+'L'+(b[0]-ux*2)+' '+(b[1]-uy*2)+'L'+c[0]+' '+c[1]+'Z';pos-=9}
 if(p)pos-=2;for(i=0;i<f;i++){var a2=pt(pos,0),b2=pt(pos+4,14);out+='M'+a2[0]+' '+a2[1]+'L'+b2[0]+' '+b2[1];pos-=7}
 if(h){if(!p&&!f)pos-=7;var a3=pt(pos,0),b3=pt(pos+2,7);out+='M'+a3[0]+' '+a3[1]+'L'+b3[0]+' '+b3[1]}
 return '<path d="'+out+'" fill="currentColor" stroke="currentColor" stroke-width="2"/>'}
