 function frame(ts){if(!alive(root))return;if(lt==null)lt=ts;var dt=(ts-lt)/1000;lt=ts;if(s.t<5){s.t=Math.min(5,s.t+dt*.6);s.v=target()+(s.v0-target())*Math.exp(-s.t);draw()}requestAnimationFrame(frame)}
