   for(i=0;i<full;i++){bx=ex-ux*pos;by=ey-uy*pos;h+='<path d="M'+bx+' '+by+'L'+(bx+px*14)+' '+(by+py*14)+'" stroke="currentColor" stroke-width="2.4"/>';pos+=6}
