 var o=[];for(i=0;i<t.length;i++){var a=t[i],b=t[i+1];o.push(a);if(!b)break;
  var aEnd=a.n!=null||(a.w&&!FN1[a.w])||a.o===')',bStart=b.n!=null||b.w||b.o==='(';
  if(aEnd&&bStart)o.push({o:'*'})}
