function splitTop(s,sep){var o=[],d=0,b=0;for(var i=0;i<s.length;i++){var c=s[i];if(c==='(')d++;else if(c===')')d--;else if(c===sep&&d===0){o.push(s.slice(b,i));b=i+1}}o.push(s.slice(b));return o}
